    "timing_mode": "measured_caption_boundaries",
    "cue_plan": "Provisional authored cue estimate for the silent two-treatment comparison only, projected from measured take 5 and take 6 rates. board_retime.py replaces it with measured_caption_boundaries after acoustic alignment; it approves nothing.",
    "clauses": [
      {
        "id": "n1a",
        "text": "Some people could have ankle-deep water in their yard.",
        "cue_ids": [
          "c1"
