        ]
      },
      {
        "id": "n1b",
        "text": "UT San Antonio says the phone warning can come after that.",
        "cue_ids": [
          "c2"
        ],
        "scene_id": "s1",
        "subject_ids": [
          "s1-water"
        ],
        "action_id": "yard-floods-before-warning",
