        "start_s": 4.24,
        "end_s": 8.28,
        "word_range": [
          9,
          20
        ]
      },
      {
        "id": "n2a",
        "text": "So its researchers built a flood station.",
        "cue_ids": [
          "c3"
        ],
        "scene_id": "s2",
        "subject_ids": [
          "s2-station",
          "s2-panel"
        ],
        "action_id": "self-power-no-tower",
        "claim_ids": [
