        ],
        "event_ids": [
          "s2-event-1"
        ],
        "start_s": 8.96,
        "end_s": 11.22,
        "word_range": [
          20,
          27
        ]
      },
      {
        "id": "n2b",
        "text": "It charges itself from light and needs no cell tower.",
        "cue_ids": [
          "c4"
        ],
        "scene_id": "s2",
        "subject_ids": [
          "s2-station",
          "s2-panel"
        ],
        "action_id": "self-power-no-tower",
        "claim_ids": [
          "c5",
          "c6",
