        ],
        "event_ids": [
          "s2-event-2",
          "s2-event-3"
        ],
        "start_s": 11.9,
        "end_s": 14.96,
        "word_range": [
          27,
          37
        ]
      },
      {
        "id": "n3a",
        "text": "Four optical sensors at different heights watch the water.",
        "cue_ids": [
          "c5"
        ],
        "scene_id": "s3",
        "subject_ids": [
          "s3-stack"
        ],
        "action_id": "sense-water-and-weather",
