          "s3-event-3"
        ],
        "start_s": 15.9,
        "end_s": 19.14,
        "word_range": [
          37,
          46
        ]
      },
      {
        "id": "n4a",
        "text": "A small chip on the station runs the AI itself.",
        "cue_ids": [
          "c6"
        ],
        "scene_id": "s4",
        "subject_ids": [
          "s4-chip",
          "s4-traces"
