        "end_s": 23.18,
        "word_range": [
          46,
          56
        ]
      },
      {
        "id": "n4b",
        "text": "So it judges flood risk without a central server.",
        "cue_ids": [
          "c7"
        ],
        "scene_id": "s4",
        "subject_ids": [
          "s4-chip",
          "s4-traces"
