  "captions": [
    {
      "id": "c1",
      "start": 0.58,
      "end": 3.58,
      "text": "Some people could have ankle-deep water in their yard.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c2",
      "start": 4.24,
      "end": 8.28,
      "text": "UT San Antonio says the phone warning can come after that.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c3",
      "start": 8.96,
      "end": 11.22,
      "text": "So its researchers built a flood station.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c4",
      "start": 11.9,
      "end": 14.96,
      "text": "It charges itself from light and needs no cell tower.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c5",
      "start": 15.9,
      "end": 19.14,
      "text": "Four optical sensors at different heights watch the water.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c6",
      "start": 19.94,
      "end": 23.18,
      "text": "A small chip on the station runs the AI itself.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c7",
      "start": 23.8,
      "end": 26.52,
      "text": "So it judges flood risk without a central server.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c8",
      "start": 27.36,
      "end": 30.7,
      "text": "Its radio signal can carry more than a half-mile in streets.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c9",
      "start": 31.56,
      "end": 34.74,
      "text": "In open country, up to five miles, to a hub.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c10",
      "start": 35.54,
      "end": 38.58,
      "text": "At the hub, a second, larger AI maps",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c11",
      "start": 38.7,
      "end": 40.24,
      "text": "flood paths for responders.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c12",
      "start": 41.22,
      "end": 44.52,
      "text": "The university reports early chip AI validation.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c13",
      "start": 45.24,
      "end": 48.48,
      "text": "Accuracy was ninety eight point eight two percent.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c14",
      "start": 49.48,
      "end": 51.82,
      "text": "The announcement reports no field result.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c15",
      "start": 52.5,
      "end": 54.8,
      "text": "It names no town with an installed station.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    },
    {
      "id": "c16",
      "start": 55.78,
      "end": 57.36,
      "text": "Deployment is still the goal.",
      "source": "measured_boundary",
      "start_measured": true,
      "end_measured": true
    }
  ],
